def heading_record(heading) -> dict | None:
    label = " ".join(heading.text_content().split())
    match = CODE_RE.search(label)
    internal_code = MUSTER_SUBSECTIONS.get(heading.get("id"))
    if not match and not internal_code:
        return None
    code = internal_code or match.group(1)
    title = label if internal_code else (label[:match.start()] + label[match.end():]).strip(" -")
    holder = html.Element("div")
    if heading.tail and heading.tail.strip():
        holder.text = heading.tail
    sibling = heading.getnext()
    while sibling is not None:
        independent = sibling.get("id") in {*MUSTER_SUBSECTIONS, "Desperate-Escape-Test"}
        numbered = sibling.tag in {"h2", "h3"} and CODE_RE.search(" ".join(sibling.text_content().split()))
        if sibling.tag in {"h1", "h2"} or independent or numbered:
            break
        holder.append(deepcopy(sibling))
        sibling = sibling.getnext()
    text = clean_text(holder)
    return {
        "code": code, "sourceCode": "25.04" if internal_code else code,
        "title": title or code, "text": text,
        "sourceNode": {"sourceUrl": SOURCE_URL, "code": "25.04" if internal_code else code, "anchor": heading.get("id")},
    }
